     1	/**
     2	 * Allow-list guard for hrefs that originate outside the codebase.
     3	 *
     4	 * Anything reaching an `href` from Contentful, a URL parameter, or a prop supplied by a
     5	 * caller we do not control has to pass through here first. `javascript:` and `data:` URLs
     6	 * execute; an authority reference like `//host` silently leaves the site. The `(?![/\\])`
     7	 * lookahead rejects that, including the backslash form — a browser treats `/\host` as `//host`,
     8	 * so a backslash is an authority reference just as much as a second slash is. `e9c2180` closed
     9	 * only the forward-slash half; the backslash and control-character forms stayed open until now.
    10	 *
    11	 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
    12	 * and browsers keep adding them.
    13	 */
    14	// eslint-disable no-control-regex — the control characters ARE the subject here. The rule exists
    15	// to catch them appearing by accident; these are deliberate, and matching them is the whole point
    16	// of the fix. Suppressed at the point of use rather than in .eslintrc, per the escape-hatch
    17	// convention in .claude/rules/typescript.md.
    18	/* eslint-disable no-control-regex */
    19	const C0_OR_SPACE = /^[\u0000-\u0020]+|[\u0000-\u0020]+$/g;
    20	const TAB_LF_CR = /[\u0009\u000a\u000d]/g;
    21	/* eslint-enable no-control-regex */
    22	
    23	/**
    24	 * Normalise the way the URL parser will, before testing.
    25	 *
    26	 * The WHATWG parser strips leading and trailing C0-or-space, and removes tab/LF/CR from anywhere
    27	 * in the input, BEFORE it parses. `/\u0009/evil.com` is therefore parsed as `//evil.com`. Testing
    28	 * the raw string means the allow-list checks a different value than the browser resolves — which
    29	 * is exactly how the earlier fix passed its own tests while leaving the hole open.
    30	 *
    31	 * A plain space is deliberately not stripped: the parser percent-encodes it rather than removing
    32	 * it, so `/ /evil.com` resolves on-site and must stay allowed.
    33	 */
    34	const normalise = (href: string): string => href.replace(C0_OR_SPACE, '').replace(TAB_LF_CR, '');
    35	
    36	const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?![/\\]))/i;
    37	
    38	/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
    39	export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(normalise(href)) : false);

=== useZimmTextInputState.ts ===
     1	import { useRef, useState } from 'react';
     2	import type React from 'react';
     3	
     4	type UseZimmTextInputStateParams = {
     5	  onChange?: (value: string) => void;
     6	  /** Controlled value. When provided the caller owns the value and internal state is unused. */
     7	  value?: string;
     8	  /** Seed for the uncontrolled case. Ignored when `value` is provided. */
     9	  defaultValue?: string;
    10	};
    11	
    12	type UseZimmTextInputStateReturn = {
    13	  value: string;
    14	  focused: boolean;
    15	  inputRef: React.RefObject<HTMLInputElement>;
    16	  handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
    17	  handleClear: () => void;
    18	  setFocused: React.Dispatch<React.SetStateAction<boolean>>;
    19	};
    20	
    21	/**
    22	 * Manages the interaction state for ZimmTextInput that the theme cannot express: the value,
    23	 * and focus. The floated-label decision is NOT made here — the label colour and the border
    24	 * and label colour cascades live in `theme/components/zimmTextInput.ts`, which receives
    25	 * `focused` and `filled` as recipe props. Hover is a CSS pseudo-class in that recipe, so it
    26	 * costs no React state.
    27	 *
    28	 * Supports both modes, following the React convention: pass `value` to control it from a
    29	 * parent (a form, or ZimmInputAction), or omit it and the hook owns the value internally,
    30	 * seeded from `defaultValue`. `onChange` fires in both modes.
    31	 * @returns value, focus flag, the input ref, and the event handlers
    32	 */
    33	export const useZimmTextInputState = ({
    34	  onChange,
    35	  value: controlledValue,
    36	  defaultValue,
    37	}: UseZimmTextInputStateParams): UseZimmTextInputStateReturn => {
    38	  // Controlled when the caller passes `value`; otherwise the hook owns it, seeded from
    39	  // `defaultValue`. Reading through this indirection is what makes the returned `value`
    40	  // correct in both modes — and the recipe derives the floated-label state from it.
    41	  const isControlled = controlledValue !== undefined;
    42	  const [internalValue, setInternalValue] = useState(defaultValue ?? '');
    43	  const value = isControlled ? controlledValue : internalValue;
    44	  const [focused, setFocused] = useState(false);
    45	  const inputRef = useRef<HTMLInputElement>(null);
    46	
    47	  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    48	    if (!isControlled) setInternalValue(e.target.value);
    49	    onChange?.(e.target.value);
    50	  };
    51	
    52	  const handleClear = () => {
    53	    if (!isControlled) setInternalValue('');
    54	    onChange?.('');
    55	    inputRef.current?.focus();
    56	  };
    57	
    58	  return { value, focused, inputRef, handleChange, handleClear, setFocused };
    59	};

