     1	import { useRef, useState } from 'react';
     2	import type React from 'react';
     3	
     4	type UseZimmTextInputStateParams = {
     5	  onChange?: (value: string) => void;
     6	  /** Controlled value. When provided the caller owns the value and internal state is unused. */
     7	  value?: string;
     8	  /** Seed for the uncontrolled case. Ignored when `value` is provided. */
     9	  defaultValue?: string;
    10	};
    11	
    12	type UseZimmTextInputStateReturn = {
    13	  value: string;
    14	  focused: boolean;
    15	  inputRef: React.RefObject<HTMLInputElement>;
    16	  handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
    17	  handleClear: () => void;
    18	  setFocused: React.Dispatch<React.SetStateAction<boolean>>;
    19	};
    20	
    21	/**
    22	 * Manages the interaction state for ZimmTextInput that the theme cannot express: the value,
    23	 * and focus. The floated-label decision is NOT made here — the label colour and the border
    24	 * and label colour cascades live in `theme/components/zimmTextInput.ts`, which receives
    25	 * `focused` and `filled` as recipe props. Hover is a CSS pseudo-class in that recipe, so it
    26	 * costs no React state.
    27	 *
    28	 * Supports both modes, following the React convention: pass `value` to control it from a
    29	 * parent (a form, or ZimmInputAction), or omit it and the hook owns the value internally,
    30	 * seeded from `defaultValue`. `onChange` fires in both modes.
    31	 * @returns value, focus flag, the input ref, and the event handlers
    32	 */
    33	export const useZimmTextInputState = ({
    34	  onChange,
    35	  value: controlledValue,
    36	  defaultValue,
    37	}: UseZimmTextInputStateParams): UseZimmTextInputStateReturn => {
    38	  // Controlled when the caller passes `value`; otherwise the hook owns it, seeded from
    39	  // `defaultValue`. Reading through this indirection is what makes the returned `value`
    40	  // correct in both modes — and the recipe derives the floated-label state from it.
    41	  const isControlled = controlledValue !== undefined;
    42	  const [internalValue, setInternalValue] = useState(defaultValue ?? '');
    43	  const value = isControlled ? controlledValue : internalValue;
    44	  const [focused, setFocused] = useState(false);
    45	  const inputRef = useRef<HTMLInputElement>(null);
    46	
    47	  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    48	    if (!isControlled) setInternalValue(e.target.value);
    49	    onChange?.(e.target.value);
    50	  };
    51	
    52	  const handleClear = () => {
    53	    if (!isControlled) setInternalValue('');
    54	    onChange?.('');
    55	    inputRef.current?.focus();
    56	  };
    57	
    58	  return { value, focused, inputRef, handleChange, handleClear, setFocused };
    59	};

