#!/bin/bash
# PostToolUse hook: after writing a new component or hook source file,
# remind to create a test file if one does not already exist.

set -euo pipefail

input=$(cat)

file_path=$(python3 -c "
import sys, json
try:
    d = json.load(sys.stdin)
    p = (d.get('tool_input') or {}).get('file_path', '')
    print(p)
except Exception:
    print('')
" <<< "$input" 2>/dev/null || true)

[[ -z "$file_path" ]] && exit 0

# Scope: component and hook source files only
if [[ ! "$file_path" =~ /app/(components|hooks)/ ]]; then
  exit 0
fi

# Skip test files, stories, and Contentful definitions
if [[ "$file_path" =~ \.(test|spec)\. ]] || \
   [[ "$file_path" =~ \.stories\. ]] || \
   [[ "$file_path" =~ ContentfulDefinition ]]; then
  exit 0
fi

# Only JS/TS source files
if [[ ! "$file_path" =~ \.(js|jsx|ts|tsx)$ ]]; then
  exit 0
fi

# Check for a test file with any common extension variant
base="${file_path%.*}"
ext="${file_path##*.}"
